    "description": "Willow Tit, a species of bird that has suffered a dramatic population decline over the past thirty years across Europe, and esp in Britain where it is an RSPB 'red status' bird. This image shows features that may differentiate it from the similar, but more common, Marsh Tit Poecile palustris: sooty cap, untidy bib, pale wing panel, larger white cheek, lack of pale patch on upper mandible. A definitive ID is usually obtained from its call.",
